import { describe, it, expect } from 'vitest'
import { create{Factory}Factory } from '~/utils/factories/{factory}/{Factory}Factory'

describe('{Factory}Factory', () => {

  describe('VariantA', () => {
    const factory = create{Factory}Factory('variantA')

    it('createProductA() retourne la config variante A', () => {
      const product = factory.createProductA()
      expect(product).toBeDefined()
      // Ajoute ici les assertions spécifiques à la variante A
    })

    it('createProductB() retourne la config variante A', () => {
      const product = factory.createProductB()
      expect(product).toBeDefined()
      // Ajoute ici les assertions spécifiques à la variante A
    })
  })

  describe('VariantB', () => {
    const factory = create{Factory}Factory('variantB')

    it('createProductA() retourne la config variante B', () => {
      const product = factory.createProductA()
      expect(product).toBeDefined()
      // Ajoute ici les assertions spécifiques à la variante B
    })

    it('createProductB() retourne la config variante B', () => {
      const product = factory.createProductB()
      expect(product).toBeDefined()
      // Ajoute ici les assertions spécifiques à la variante B
    })
  })

  describe('Cohérence de la famille', () => {
    it('les deux variantes implémentent toutes les méthodes de l\'interface', () => {
      const variantA = create{Factory}Factory('variantA')
      const variantB = create{Factory}Factory('variantB')
      expect(typeof variantA.createProductA).toBe('function')
      expect(typeof variantA.createProductB).toBe('function')
      expect(typeof variantB.createProductA).toBe('function')
      expect(typeof variantB.createProductB).toBe('function')
    })

    it('les produits A et B sont distincts entre variantes', () => {
      const variantA = create{Factory}Factory('variantA')
      const variantB = create{Factory}Factory('variantB')
      expect(variantA.createProductA()).not.toEqual(variantB.createProductA())
    })
  })

})

